package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

var reader = bufio.NewReader(os.Stdin)
var writer = bufio.NewWriter(os.Stdout)

func readString() string {
	line, _ := reader.ReadString('\n')
	return strings.TrimRight(line, "\r\n")
}

func readStrings() []string {
	return strings.Split(readString(), " ")
}

func readInt() int {
	n, _ := strconv.Atoi(readString())
	return n
}

func readInts() []int {
	parts := readStrings()
	res := make([]int, len(parts))
	for i, p := range parts {
		res[i], _ = strconv.Atoi(p)
	}
	return res
}

func readLong() int64 {
	n, _ := strconv.ParseInt(readString(), 10, 64)
	return n
}

func readLongs() []int64 {
	parts := readStrings()
	res := make([]int64, len(parts))
	for i, p := range parts {
		res[i], _ = strconv.ParseInt(p, 10, 64)
	}
	return res
}

func readDouble() float64 {
	n, _ := strconv.ParseFloat(readString(), 64)
	return n
}

func readDoubles() []float64 {
	parts := readStrings()
	res := make([]float64, len(parts))
	for i, p := range parts {
		res[i], _ = strconv.ParseFloat(p, 64)
	}
	return res
}

func main() {
	defer writer.Flush()
	nums := readInts()
	k, r := nums[0], nums[1]
	i := 1
	for {
		if (i*k)%10 == 0 || (i*k-r)%10 == 0 {
			fmt.Fprint(writer, i)
			break
		}
		i++
	}
}
